import torch

def axial_attention(x, W_q, W_k, W_v, axis="height"):
    B, C, H, W = x.shape
    if axis == "height":
        seq = x.permute(0, 3, 2, 1).reshape(B * W, H, C)
    elif axis == "width":
        seq = x.permute(0, 2, 3, 1).reshape(B * H, W, C)
    else:
        raise ValueError("axis must be 'height' or 'width'")
    q, k, v = seq @ W_q, seq @ W_k, seq @ W_v
    out = torch.softmax((q @ k.transpose(-2, -1)) / (C ** 0.5), dim=-1) @ v
    if axis == "height":
        return out.reshape(B, W, H, C).permute(0, 3, 2, 1)
    return out.reshape(B, H, W, C).permute(0, 3, 1, 2)

def beam_search(log_prob_fn, start_token, max_len, beam_width, eos_token):
    beams = [(0.0, [start_token])]
    completed = []
    for _ in range(max_len):
        candidates = []
        for score, seq in beams:
            if seq[-1] == eos_token:
                completed.append((score, seq))
                continue
            log_probs = log_prob_fn(torch.tensor(seq))
            topk_lp, topk_idx = log_probs.topk(beam_width)
            for j in range(beam_width):
                candidates.append((score + topk_lp[j].item(), seq + [topk_idx[j].item()]))
        if not candidates:
            break
        candidates.sort(key=lambda x: x[0], reverse=True)
        beams = candidates[:beam_width]
    all_seqs = completed + beams
    all_seqs.sort(key=lambda x: x[0], reverse=True)
    return all_seqs[0][1]

def cosine_lr_schedule(step, total_steps, warmup_steps, max_lr, min_lr=0.0):
    if step < warmup_steps:
        return max_lr * step / warmup_steps
    if step >= total_steps:
        return min_lr
    progress = (step - warmup_steps) / (total_steps - warmup_steps)
    return min_lr + 0.5 * (max_lr - min_lr) * (1.0 + math.cos(math.pi * progress))

import torch

def deepnorm_step(x, sublayer_out, gamma, beta, num_layers, eps=1e-5):
    alpha = (2.0 * num_layers) ** 0.25
    beta_gain = (8.0 * num_layers) ** (-0.25)
    u = x * alpha + sublayer_out
    mean = u.mean(dim=-1, keepdim=True)
    var = u.var(dim=-1, keepdim=True, unbiased=False)
    normalized = gamma * (u - mean) / torch.sqrt(var + eps) + beta
    return normalized, float(beta_gain)

import torch

def my_group_norm(x, num_groups, gamma, beta, eps=1e-5):
    B, C, H, W = x.shape
    grouped = x.reshape(B, num_groups, C // num_groups, H, W)
    mean = grouped.mean(dim=(2, 3, 4), keepdim=True)
    var = grouped.var(dim=(2, 3, 4), keepdim=True, unbiased=False)
    normalized = ((grouped - mean) / torch.sqrt(var + eps)).reshape(B, C, H, W)
    return gamma.view(1, C, 1, 1) * normalized + beta.view(1, C, 1, 1)

import torch

def schulman_kl_estimators(logp_policy, logp_ref, mask=None):
    log_ratio = logp_policy - logp_ref
    values = (
        log_ratio,
        0.5 * log_ratio.square(),
        torch.exp(-log_ratio) + log_ratio - 1.0,
    )
    if mask is None:
        return tuple(x.mean() for x in values)
    denominator = mask.sum().clamp(min=1.0)
    return tuple((x * mask).sum() / denominator for x in values)

