import torch.nn.functional as F

def orpo_loss(chosen_avg_logps, rejected_avg_logps, lambda_or=0.1, eps=1e-6):
    sft_loss = -chosen_avg_logps.mean()
    def log_odds(logp):
        return logp - torch.log((1.0 - torch.exp(logp)).clamp(min=eps))
    log_odds_ratio = log_odds(chosen_avg_logps) - log_odds(rejected_avg_logps)
    pref_loss = -F.logsigmoid(log_odds_ratio).mean()
    total_loss = sft_loss + lambda_or * pref_loss
    return total_loss, sft_loss, pref_loss

import torch

class LionOptimizer:
    def __init__(self, params, lr=1e-4, betas=(0.9, 0.99), weight_decay=0.0):
        self.params = list(params)
        self.lr = lr
        self.beta1, self.beta2 = betas
        self.weight_decay = weight_decay
        self.m = [torch.zeros_like(p) for p in self.params]

    def step(self):
        with torch.no_grad():
            for i, p in enumerate(self.params):
                if p.grad is None:
                    continue
                g = p.grad
                p.mul_(1.0 - self.lr * self.weight_decay)
                u = torch.sign(self.beta1 * self.m[i] + (1.0 - self.beta1) * g)
                p.sub_(self.lr * u)
                self.m[i].mul_(self.beta2).add_(g, alpha=1.0 - self.beta2)

    def zero_grad(self):
        for p in self.params:
            if p.grad is not None:
                p.grad.zero_()

import torch

def colbert_maxsim(query_toks, doc_toks, query_mask=None, doc_mask=None, eps=1e-8):
    q = query_toks / (query_toks.norm(dim=-1, keepdim=True) + eps)
    d = doc_toks / (doc_toks.norm(dim=-1, keepdim=True) + eps)
    sim = q @ d.transpose(-1, -2)
    if doc_mask is not None:
        sim = sim.masked_fill(doc_mask.unsqueeze(-2) == 0, float("-inf"))
    maxima = sim.max(dim=-1).values
    if query_mask is not None:
        maxima = maxima.masked_fill(query_mask == 0, 0.0)
    return maxima.sum(dim=-1)

import torch

def pass_at_k(n, c, k):
    n_float = n.to(dtype=torch.float32)
    c_float = c.to(device=n.device, dtype=torch.float32)
    result = torch.empty_like(n_float)
    for i in range(n.numel()):
        if n_float[i] - c_float[i] < k:
            result[i] = 1.0
        else:
            failure = torch.ones((), device=n.device, dtype=torch.float32)
            for j in range(k):
                failure = failure * ((n_float[i] - c_float[i] - j) / (n_float[i] - j))
            result[i] = 1.0 - failure
    return result

def apply_rope(q, k):
    B, S, D = q.shape
    pos = torch.arange(S, device=q.device).unsqueeze(1).float()
    dim = torch.arange(0, D, 2, device=q.device).float()
    freqs = 1.0 / (10000.0 ** (dim / D))
    angles = pos * freqs
    cos_a = torch.cos(angles)
    sin_a = torch.sin(angles)

    def rotate(x):
        x1, x2 = x[..., 0::2], x[..., 1::2]
        return torch.stack([x1 * cos_a - x2 * sin_a,
                            x1 * sin_a + x2 * cos_a], dim=-1).flatten(-2)

    return rotate(q), rotate(k)

import torch

def tree_speculative_mask(parent_indices):
    parents = torch.as_tensor(parent_indices)
    N = parents.numel()
    mask = torch.zeros((N, N), dtype=torch.bool, device=parents.device)
    for i in range(N):
        if i > 0:
            mask[i] = mask[parents[i]]
        mask[i, i] = True
    return mask

def wordpiece_encode(text, vocab, unk_token='[UNK]', max_chars=100):
    output = []
    for word in text.strip().split():
        if len(word) > max_chars:
            output.append(unk_token)
            continue
        pieces = []
        start = 0
        failed = False
        while start < len(word):
            match = None
            match_end = start
            for end in range(len(word), start, -1):
                candidate = word[start:end]
                if start > 0:
                    candidate = '##' + candidate
                if candidate in vocab:
                    match = candidate
                    match_end = end
                    break
            if match is None:
                failed = True
                break
            pieces.append(match)
            start = match_end
        if failed:
            output.append(unk_token)
        else:
            output.extend(pieces)
    return output

class SimpleBPE:
    """
    Byte-Pair Encoding (BPE) module.
    """
    def __init__(self):  # 初始化: 定义模型结构和参数
        # Initialize layers and parameters
        self.merges = []

    def train(self, corpus, num_merges):
        vocab = {}
        for word in corpus:
            symbols = tuple(word) + ('</w>',)
            vocab[symbols] = vocab.get(symbols, 0) + 1
        self.merges = []
        for _ in range(num_merges):
            pairs = {}
            for word, freq in vocab.items():
                for i in range(len(word) - 1):
                    pair = (word[i], word[i + 1])
                    pairs[pair] = pairs.get(pair, 0) + freq
            if not pairs:
                break
            best = max(pairs, key=pairs.get)
            self.merges.append(best)
            new_vocab = {}
            for word, freq in vocab.items():
                new_word = []
                i = 0
                while i < len(word):
                    if i < len(word) - 1 and (word[i], word[i + 1]) == best:
                        new_word.append(word[i] + word[i + 1])
                        i += 2
                    else:
                        new_word.append(word[i])
                        i += 1
                new_vocab[tuple(new_word)] = freq
            vocab = new_vocab

    def encode(self, text):
        all_tokens = []
        for word in text.split():
            symbols = list(word) + ['</w>']
            for a, b in self.merges:
                i = 0
                while i < len(symbols) - 1:
                    if symbols[i] == a and symbols[i + 1] == b:
                        symbols = symbols[:i] + [a + b] + symbols[i + 2:]
                    else:
                        i += 1
            all_tokens.extend(symbols)
        return all_tokens

import torch

def dapo_loss(new_logps, old_logps, advantages, action_mask,
              eps_low=0.2, eps_high=0.28):
    adv = advantages.detach()
    if adv.dim() == 1:
        adv = adv.unsqueeze(-1)
    ratio = torch.exp(new_logps - old_logps.detach())
    clipped_ratio = torch.clamp(ratio, 1.0 - eps_low, 1.0 + eps_high)
    surr = torch.minimum(ratio * adv, clipped_ratio * adv)
    return -(surr * action_mask).sum() / action_mask.sum().clamp(min=1.0)

def speculative_decode(target_probs, draft_probs, draft_tokens):
    K = len(draft_tokens)
    accepted = []
    for i in range(K):
        t = draft_tokens[i].item()
        ratio = target_probs[i, t] / max(draft_probs[i, t].item(), 1e-10)
        if torch.rand(1).item() < min(1.0, ratio.item()):
            accepted.append(t)
        else:
            adjusted = torch.clamp(target_probs[i] - draft_probs[i], min=0)
            s = adjusted.sum()  # 求和
            if s > 0:
                adjusted = adjusted / s
            else:
                adjusted = torch.ones_like(adjusted) / adjusted.shape[0]
            accepted.append(torch.multinomial(adjusted, 1).item())
            return accepted
    return accepted

def unigram_viterbi(text, token_log_probs, unk_log_prob=-10.0):
    n = len(text)
    best_score = [float('-inf')] * (n + 1)
    backptr = [-1] * (n + 1)
    best_score[0] = 0.0
    for end in range(1, n + 1):
        for start in range(end):
            piece = text[start:end]
            if piece in token_log_probs:
                score = best_score[start] + token_log_probs[piece]
                if score > best_score[end]:
                    best_score[end] = score
                    backptr[end] = start
        char = text[end - 1:end]
        if char not in token_log_probs and best_score[end] == float('-inf'):
            best_score[end] = best_score[end - 1] + unk_log_prob
            backptr[end] = end - 1
    pieces = []
    end = n
    while end > 0:
        start = backptr[end]
        pieces.append(text[start:end])
        end = start
    pieces.reverse()
    return pieces, float(best_score[n])
